const commits = $input.all().filter(item => item.json.type === 'commits') || [];
const issues = $input.all().filter(item => item.json.type === 'issues') || [];
const prs = $input.all().filter(item => item.json.type === 'prs') || [];

const repoName = $env.GITHUB_REPO_DEFAULT || 'unknown/repo';

return [{
  json: {
    repo: repoName,
    weekEnding: new Date().toISOString().split('T')[0],
    commitCount: commits.length,
    commits: commits.slice(0, 10).map(c => ({
      author: c.json.commit?.author?.name || c.json.author?.login || 'unknown',
      message: (c.json.commit?.message || '').split('\n')[0],
      sha: (c.json.sha || '').substring(0, 7),
      url: c.json.html_url
    })),
    issueCount: issues.length,
    issues: issues.slice(0, 10).map(i => ({
      title: i.json.title,
      number: i.json.number,
      url: i.json.html_url,
      author: i.json.user?.login || 'unknown'
    })),
    prCount: prs.length,
    pullRequests: prs.slice(0, 10).map(pr => ({
      title: pr.json.title,
      number: pr.json.number,
      url: pr.json.html_url,
      author: pr.json.user?.login || 'unknown',
      merged: !!pr.json.merged_at
    }))
  }
}];

