const claudeResponse = $input.first().json;

const summary = claudeResponse.content?.[0]?.text || 'Summary generation failed';
const data = $node['Merge Activity Data'].json;

const formatted = `# Weekly Development Summary

**Repository**: ${data.repo}
**Week Ending**: ${data.weekEnding}
**Generated by**: Claude Sonnet + n8n

## Stats
- Commits: ${data.commitCount}
- Issues Closed: ${data.issueCount}
- PRs Merged: ${data.prCount}

## Summary
${summary}

---
*This summary was automatically generated by the n8n + Claude weekly dev summary workflow.*`;

return [{json: {summary: formatted, markdown: formatted, repo: data.repo, weekEnding: data.weekEnding}}];
